import pytest
import click
from click.shell_completion import CompletionItem

class Foo(click.ParamType):
    def convert(self, value, param, ctx):
        return value

    def shell_complete(self, ctx, param, incomplete):
        return [
            CompletionItem(value=value, help="adsf") for value in
            ["baz:quux", "spam:eggs"]
        ]

@click.command()
@click.argument("foo", type=Foo())
def main(foo):
    pass

def test_zsh_completion_with_colon():
    runner = click.testing.CliRunner()
    result = runner.invoke(main, ['--help'], env={
        'FOO_COMPLETE': 'zsh_source',
        '_FOO_COMPLETE': 'zsh_source'
    })
    assert "baz:quux" in result.output

import pytest
import click
from click.testing import CliRunner

def test_runner_catch_exceptions(runner):
    @click.command()
    def test():
        raise RuntimeError("Test error")

    result = runner.invoke(test, catch_exceptions=False)
    assert result.exception is not None

import pytest
import click
from click import Context, Parameter
from click.types import FuncParamType
from typing import Any, Callable

def test_func_param_type_value_error(runner):
    def func(value: Any) -> str:
        if value != 'works':
            raise ValueError(f'input was {value=}, should be works')
        return value

    class TestParamType(FuncParamType):
        def __init__(self, func: Callable[[Any], Any]) -> None:
            super().__init__(func)

    @click.command()
    @click.argument('input', type=TestParamType(func))
    def cli(input):
        pass

    result = runner.invoke(cli, ['not_works'], catch_exceptions=False)
    assert "input was 'not_works', should be works" in result.output

